// Framework sheet content — Units 5 (Agility/Disruption), 6 (Investment), 7 (Unicorns).
const C = {};

// ============ UNIT 5 — Agility, Disruption & Rebranding ============
C["OODA Loop (Enterprise)"]={
 def:"The Enterprise OODA Loop applies Boyd's Observe–Orient–Decide–Act cycle at organisational scale, treating the speed of corporate re-decision as a source of competitive advantage in fast-changing markets.",
 who:"Extends John Boyd's military OODA loop to organisations, as taken up in agile-strategy and business-agility literature.",
 why:"It was developed to argue that, under disruption, the organisation that re-decides fastest can outmanoeuvre larger, slower rivals.",
 how:"Corporate decision cycles are mapped and accelerated; AI compresses observation and orientation while humans retain fast, accountable decision and action.",
 when:"During disruption, rapid market shifts and agile-transformation efforts.",
 whom:"Senior leaders, strategists and transformation teams.",
 innov:"It reframes agility as decision tempo, making speed of re-decision — not size — the moat under AI-accelerated change.",
 sources:["Boyd, J. (1986) 'Patterns of Conflict' (briefing).","Reeves, M., Haanaes, K. and Sinha, J. (2015) Your Strategy Needs a Strategy. Boston: HBR Press."]};

C["Cynefin Framework"]={
 def:"The Cynefin Framework sorts situations into domains — clear, complicated, complex and chaotic — so that leaders match their response to the kind of problem they face rather than applying one approach to all.",
 who:"Created by Dave Snowden while at IBM, set out with Mary Boone in a 2007 Harvard Business Review article.",
 why:"It was developed to counter the error of treating every problem as merely complicated, when complex problems require probing and adaptation.",
 how:"A situation is placed in a domain; complex problems are met with safe-to-fail experiments and amplification of what works, not detailed up-front planning.",
 when:"When deciding how to respond to disruption and uncertainty.",
 whom:"Leaders, strategists and decision-makers.",
 innov:"It introduces a sense-making typology that prevents misapplied management approaches, especially in the complex domain where disruption lives.",
 sources:["Snowden, D.J. and Boone, M.E. (2007) 'A leader's framework for decision making', Harvard Business Review, 85(11).","Kurtz, C.F. and Snowden, D.J. (2003) 'The new dynamics of strategy', IBM Systems Journal, 42(3)."]};

C["Agile Operating Model"]={
 def:"An Agile Operating Model organises work around small, cross-functional teams with fast feedback loops, enabling rapid responsiveness in place of slow, hierarchical decision-making.",
 who:"Synthesised from agile software practice and scaled-agile thinking, popularised for whole organisations by writers such as Aghina and colleagues at McKinsey.",
 why:"It was developed to give organisations the responsiveness that fast-changing, AI-shaped markets demand.",
 how:"Work is reorganised into empowered teams with clear missions and fast feedback; governance lightens to allow speed within guardrails.",
 when:"During agile transformation and when responsiveness becomes a strategic priority.",
 whom:"Executives, transformation leaders and team leads.",
 innov:"It scales agile principles from software to the enterprise, structurally enabling the decision speed agility requires.",
 sources:["Aghina, W. et al. (2018) 'The five trademarks of agile organizations', McKinsey & Company.","Rigby, D.K., Sutherland, J. and Takeuchi, H. (2016) 'Embracing agile', Harvard Business Review, 94(5)."]};

C["Sense-Respond Loop"]={
 def:"The Sense-Respond Loop is a model of continuous adaptation in which an organisation senses signals from its environment and responds rapidly, iterating rather than executing a fixed long-range plan.",
 who:"Articulated by Stephan Haeckel in Adaptive Enterprise (1999) as an alternative to make-and-sell models.",
 why:"It was developed for environments too turbulent for predictive planning, where responsiveness beats forecasting.",
 how:"The organisation builds capability to sense early and respond fast, treating strategy as continuous adaptation.",
 when:"In volatile markets and during AI-driven disruption.",
 whom:"Strategists and operating leaders.",
 innov:"It reframes strategy from prediction to adaptation, aligning with agile and OODA thinking under uncertainty.",
 sources:["Haeckel, S.H. (1999) Adaptive Enterprise: Creating and Leading Sense-and-Respond Organizations. Boston: HBS Press.","Reeves, M., Levin, S. and Ueda, D. (2016) 'The biology of corporate survival', Harvard Business Review, 94(1)."]};

C["Real Options Lens"]={
 def:"The Real Options Lens treats strategic investments as options — small commitments that buy the right, but not the obligation, to invest further — valuing flexibility under uncertainty.",
 who:"Adapted from financial-options theory to strategy by scholars including Timothy Luehrman and the real-options literature.",
 why:"It was developed to value managerial flexibility, which traditional discounted-cash-flow analysis undervalues in uncertain settings.",
 how:"Initiatives are structured as staged options; small bets preserve the right to scale, abandon or pivot as uncertainty resolves.",
 when:"When investing under high uncertainty, including AI bets with unclear payoffs.",
 whom:"Strategy, finance and innovation leaders.",
 innov:"It values the flexibility to wait, expand or abandon — a natural fit for sequencing uncertain AI investments.",
 sources:["Luehrman, T.A. (1998) 'Strategy as a portfolio of real options', Harvard Business Review, 76(5).","Dixit, A.K. and Pindyck, R.S. (1994) Investment Under Uncertainty. Princeton: PUP."]};

C["Disruption S-Curves"]={
 def:"Disruption S-Curves plot the performance trajectories of incumbent and entrant technologies over time, showing how an initially inferior entrant can overtake an incumbent as its curve steepens.",
 who:"Rooted in technology-S-curve analysis (Foster) and central to Clayton Christensen's theory of disruptive innovation.",
 why:"It was developed to explain how disruptors that start below incumbents' performance can eventually surpass them, often unnoticed until too late.",
 how:"Incumbent and entrant trajectories are plotted; the crossover point and the incumbent's vulnerability are assessed.",
 when:"When analysing disruptive threats and timing strategic responses.",
 whom:"Strategists, innovation leaders and executives.",
 innov:"It visualises why good firms miss disruption — they track the wrong curve — underpinning the Innovator's Dilemma.",
 sources:["Foster, R.N. (1986) Innovation: The Attacker's Advantage. New York: Summit.","Christensen, C.M. (1997) The Innovator's Dilemma. Boston: HBS Press."]};

C["Innovator's Dilemma"]={
 def:"The Innovator's Dilemma is the finding that well-managed incumbents can fail precisely because they listen to their best customers and invest in sustaining innovations, leaving them exposed to disruptive entrants.",
 who:"Articulated by Clayton Christensen in The Innovator's Dilemma (1997).",
 why:"It was developed to explain the paradox that doing everything 'right' by mainstream-customer logic can cause incumbents to lose to initially inferior disruptors.",
 how:"The firm examines whether disruptive threats are dismissed because they serve undemanding or new segments, and whether it can pursue them without cannibalising the core.",
 when:"When facing potential disruption and deciding how to respond.",
 whom:"Executives, strategists and innovation leaders.",
 innov:"It overturned the assumption that incumbents fail through complacency, showing that competence at the core can itself be the vulnerability.",
 sources:["Christensen, C.M. (1997) The Innovator's Dilemma. Boston: HBS Press.","Christensen, C.M. and Raynor, M. (2003) The Innovator's Solution. Boston: HBS Press."]};

C["Three Horizons of Growth"]={
 def:"The Three Horizons of Growth frames the simultaneous management of defending the core (H1), building emerging businesses (H2) and creating future options (H3), so disruption does not catch the firm investing only in today.",
 who:"Introduced by Baghai, Coley and White of McKinsey in The Alchemy of Growth (1999).",
 why:"It was developed to balance exploitation of the present with exploration of the future, the failure of which leaves incumbents exposed to disruptors.",
 how:"Initiatives are sorted into horizons and funded in parallel, ensuring future growth is protected even while the core is optimised.",
 when:"During growth and innovation portfolio planning under disruption.",
 whom:"Executives and innovation governance teams.",
 innov:"It institutionalises parallel investment across time horizons, countering the short-termism that disruption exploits.",
 sources:["Baghai, M., Coley, S. and White, D. (1999) The Alchemy of Growth. Reading: Perseus.","McKinsey & Company (2009) 'Enduring Ideas: The three horizons of growth'."]};

C["Adjacent Possible Map"]={
 def:"The Adjacent Possible Map identifies the set of moves realistically reachable from a firm's current position — the adjacent possibilities — guiding expansion that builds on existing capabilities.",
 who:"Drawing on Stuart Kauffman's biological concept of the 'adjacent possible', applied to strategy and innovation.",
 why:"It was developed to focus expansion on feasible, capability-leveraging adjacencies rather than distant, unsupported leaps.",
 how:"Current capabilities and assets define the reachable adjacent moves; expansion targets the most valuable feasible adjacency.",
 when:"When planning growth and diversification under change.",
 whom:"Strategy and corporate-development teams.",
 innov:"It disciplines expansion by realistic reach, balancing ambition against capability in volatile markets.",
 sources:["Kauffman, S. (2000) Investigations. Oxford: OUP.","Johnson, S. (2010) Where Good Ideas Come From. New York: Riverhead."]};

C["Disruption Vulnerability Audit"]={
 def:"A Disruption Vulnerability Audit assesses how exposed a business model is to disruption, examining where value is created, how easily it could be unbundled, and where entrants might attack.",
 who:"A practitioner construct from disruption and business-model-innovation analysis.",
 why:"It was developed to make incumbents honestly assess their exposure before a disruptor forces the issue.",
 how:"The model is stress-tested against disruptive moves — unbundling, new entrants, AI-native rivals — and weak points identified.",
 when:"During strategic risk review and disruption planning.",
 whom:"Executives, strategists and risk leaders.",
 innov:"It converts the abstract fear of disruption into a structured self-assessment of specific vulnerabilities.",
 sources:["Christensen, C.M. (1997) The Innovator's Dilemma. Boston: HBS Press.","Wessel, M. and Christensen, C.M. (2012) 'Surviving disruption', Harvard Business Review, 90(12)."]};

C["Brand Pyramid"]={
 def:"The Brand Pyramid layers a brand from its foundational context and offering up through truths and story to its overarching purpose, providing a structured view of what a brand stands for.",
 who:"A widely used brand-strategy model with variants from agencies and brand-management practice; related to Keller's brand-equity pyramid.",
 why:"It was developed to give brand strategy a coherent structure, linking tangible offering to intangible purpose.",
 how:"Each layer is articulated from the base up; rebranding decisions are tested for consistency across the pyramid.",
 when:"During brand strategy and rebranding.",
 whom:"Brand, marketing and executive leaders.",
 innov:"It organises brand meaning hierarchically, ensuring rebrands change the right layer without fracturing the whole.",
 sources:["Keller, K.L. (2001) 'Building customer-based brand equity', Marketing Management, 10(2).","Aaker, D.A. (1996) Building Strong Brands. New York: Free Press."]};

C["12 Brand Archetypes"]={
 def:"The 12 Brand Archetypes apply Jungian archetypes — such as the Hero, Sage, Creator and Outlaw — to brands, giving each a consistent personality that shapes voice, story and positioning.",
 who:"Adapted to branding by Margaret Mark and Carol Pearson in The Hero and the Outlaw (2001), drawing on Carl Jung's archetypes.",
 why:"It was developed to give brands a coherent, resonant personality grounded in deep, universal patterns.",
 how:"A brand is matched to an archetype that guides repositioning, tone and narrative consistently across touchpoints.",
 when:"During brand definition and rebranding.",
 whom:"Brand and marketing strategists.",
 innov:"It links brand personality to enduring psychological archetypes, giving rebrands a stable foundation for new expression.",
 sources:["Mark, M. and Pearson, C.S. (2001) The Hero and the Outlaw. New York: McGraw-Hill.","Jung, C.G. (1968) The Archetypes and the Collective Unconscious. Princeton: PUP."]};

C["Rebrand Decision Matrix"]={
 def:"The Rebrand Decision Matrix distinguishes when a brand needs a light refresh, a fuller reposition, or a complete rebuild, by the scale of change required and the state of existing brand equity.",
 who:"A practitioner construct from brand-strategy and rebranding practice.",
 why:"It was developed to prevent both timid refreshes that fail to respond to disruption and reckless rebuilds that destroy equity.",
 how:"The situation is placed by required change and equity health; the matrix recommends refresh, reposition or rebuild.",
 when:"When deciding the scope of a rebrand under disruption.",
 whom:"Brand, marketing and executive leaders.",
 innov:"It matches the scale of brand change to circumstance, guarding the equity that is often the firm's real moat.",
 sources:["Aaker, D.A. (1996) Building Strong Brands. New York: Free Press.","Muzellec, L. and Lambkin, M. (2006) 'Corporate rebranding', European Journal of Marketing, 40(7/8)."]};

C["StoryBrand Framework"]={
 def:"The StoryBrand Framework structures brand messaging as a story in which the customer is the hero, the brand is the guide, and a clear plan leads to success and away from failure.",
 who:"Developed by Donald Miller in Building a StoryBrand (2017), applying narrative structure to marketing.",
 why:"It was developed to cut through unclear messaging by casting the customer, not the brand, as the hero of the story.",
 how:"Messaging is rebuilt around the seven-part story structure, with the brand positioned as the guide offering a plan.",
 when:"During brand messaging, repositioning and rebranding.",
 whom:"Marketing and brand teams.",
 innov:"It makes the customer the hero — a discipline that clarifies messaging and resists brand self-absorption.",
 sources:["Miller, D. (2017) Building a StoryBrand. Nashville: HarperCollins Leadership.","Campbell, J. (1949) The Hero with a Thousand Faces. New York: Pantheon."]};

C["Brand Equity Bridge"]={
 def:"The Brand Equity Bridge depicts how a rebrand can carry accumulated brand equity across a transition, preserving the value of recognition and trust while adopting a new identity.",
 who:"A construct from brand-management practice on managing brand transitions and migrations.",
 why:"It was developed to prevent rebrands from discarding hard-won equity, a frequent and costly error.",
 how:"Sources of equity are identified and deliberately carried across the transition through continuity cues and migration strategy.",
 when:"During rebranding, mergers and brand migrations.",
 whom:"Brand, marketing and executive leaders.",
 innov:"It treats equity transfer as a managed bridge, protecting intangible value through change.",
 sources:["Aaker, D.A. (1991) Managing Brand Equity. New York: Free Press.","Muzellec, L. and Lambkin, M. (2006) 'Corporate rebranding', European Journal of Marketing, 40(7/8)."]};

C["Kotter's 8 Steps"]={
 def:"Kotter's 8-Step Process for Leading Change sets out a sequence — from establishing urgency to anchoring change in the culture — for delivering organisational change without the common failure modes.",
 who:"Developed by John Kotter in Leading Change (1996), based on study of corporate change efforts.",
 why:"It was developed because most change programmes fail, often for want of urgency or short-term wins, which the steps address.",
 how:"Change is led through the eight steps in sequence, ensuring urgency, coalition, vision, communication, wins and anchoring.",
 when:"During organisational change, including AI-driven transformation and rebranding.",
 whom:"Change leaders, executives and transformation teams.",
 innov:"It distilled change leadership into a memorable, evidence-based sequence that remains a default playbook.",
 sources:["Kotter, J.P. (1996) Leading Change. Boston: HBS Press.","Kotter, J.P. (1995) 'Leading change: Why transformation efforts fail', Harvard Business Review, 73(2)."]};

C["ADKAR Model"]={
 def:"The ADKAR Model frames individual change through five outcomes — Awareness, Desire, Knowledge, Ability and Reinforcement — treating organisational change as the sum of successful individual transitions.",
 who:"Developed by Jeff Hiatt of Prosci, set out in ADKAR: A Model for Change (2006).",
 why:"It was developed to make change management concrete at the individual level, where organisational change ultimately succeeds or fails.",
 how:"Each person's progress through the five outcomes is supported and tracked; blockages are addressed at the specific outcome that stalls.",
 when:"During change implementation, including AI adoption.",
 whom:"Change managers, HR and team leaders.",
 innov:"It locates change in the individual, complementing organisation-level models like Kotter's with a personal-transition lens.",
 sources:["Hiatt, J. (2006) ADKAR: A Model for Change in Business, Government and Our Community. Loveland: Prosci.","Prosci (2018) Best Practices in Change Management."]};

C["Burning Platform vs. Burning Ambition"]={
 def:"This framing contrasts two motives for change — a 'burning platform' driven by threat and a 'burning ambition' driven by opportunity — recognising that change can be powered by fear or by aspiration.",
 who:"A change-leadership construct, with the burning-platform metaphor popularised in corporate-turnaround discourse and the ambition counterpoint added in later practice.",
 why:"It was developed to broaden change motivation beyond crisis, since fear-driven change can be brittle and demoralising.",
 how:"Leaders choose and communicate the motive — threat, aspiration, or both — that best mobilises the organisation for the change at hand.",
 when:"When framing and launching change and transformation.",
 whom:"Change leaders and executives.",
 innov:"It balances threat-driven urgency with opportunity-driven aspiration, offering a more sustainable basis for change.",
 sources:["Kotter, J.P. (1996) Leading Change. Boston: HBS Press.","Conner, D.R. (1992) Managing at the Speed of Change. New York: Villard."]};

C["Transition Curve"]={
 def:"The Transition Curve describes the emotional stages people pass through during disruptive change — from shock and resistance to exploration and commitment — so leaders can support each stage.",
 who:"Adapted from Elisabeth Kübler-Ross's stages of grief to organisational change by writers such as John Fisher.",
 why:"It was developed to help leaders anticipate and support the human, emotional reality of change rather than treating it as purely rational.",
 how:"Individuals are met where they are on the curve, with support tailored to their current stage to ease the transition.",
 when:"During disruptive change and transformation.",
 whom:"Change managers, HR and leaders.",
 innov:"It centres the emotional experience of change, complementing process models with human dynamics.",
 sources:["Kübler-Ross, E. (1969) On Death and Dying. New York: Macmillan.","Fisher, J.M. (2005) 'A time for change', Human Resource Development International, 8(2)."]};

C["Change Readiness Radar"]={
 def:"A Change Readiness Radar assesses an organisation's preparedness for change across dimensions such as leadership, capability, culture and resources, identifying where readiness must be built first.",
 who:"A construct from change-management practice for diagnosing readiness before launching change.",
 why:"It was developed to prevent change efforts from launching into unprepared organisations, a common cause of failure.",
 how:"Readiness dimensions are scored on a radar; weak areas are strengthened before, or alongside, the change.",
 when:"Before and during change and transformation programmes.",
 whom:"Change leaders, HR and executives.",
 innov:"It makes readiness an explicit, measured precondition rather than an assumption, improving the odds of change success.",
 sources:["Armenakis, A.A., Harris, S.G. and Mossholder, K.W. (1993) 'Creating readiness for organizational change', Human Relations, 46(6).","Prosci (2018) Best Practices in Change Management."]};

// ============ UNIT 6 — Investment Strategies in the AI Era ============
C["Modern Portfolio Theory"]={
 def:"Modern Portfolio Theory (MPT) shows how combining assets with imperfectly correlated returns reduces portfolio risk for a given expected return, defining an efficient frontier of optimal portfolios.",
 who:"Developed by Harry Markowitz in his 1952 paper 'Portfolio Selection', for which he later received the Nobel Prize.",
 why:"It was developed to formalise diversification, showing mathematically that risk depends on covariance, not just individual asset risk.",
 how:"Assets are combined to minimise variance for a target return; portfolios are selected from the efficient frontier per the investor's risk appetite.",
 when:"When constructing portfolios and assessing diversification, including AI-driven allocation.",
 whom:"Portfolio managers, investment analysts and advisers.",
 innov:"It established diversification as the 'only free lunch' in investing and founded quantitative portfolio construction — a law AI accelerates but does not repeal.",
 sources:["Markowitz, H. (1952) 'Portfolio selection', The Journal of Finance, 7(1), pp. 77–91.","Markowitz, H. (1959) Portfolio Selection: Efficient Diversification of Investments. New York: Wiley."]};

C["Risk-Return Spectrum"]={
 def:"The Risk-Return Spectrum expresses the foundational principle that higher expected returns require accepting higher risk, ordering asset classes along this trade-off.",
 who:"A foundational principle of finance, formalised through portfolio theory and the work of Markowitz, Sharpe and others.",
 why:"It was developed to make explicit that return is compensation for bearing risk, disciplining expectations of 'risk-free' high returns.",
 how:"Investments are placed on the spectrum; choices are made consistent with the investor's risk tolerance and objectives.",
 when:"When setting investment strategy and evaluating AI-driven products promising high returns.",
 whom:"Investors, advisers and analysts.",
 innov:"It anchors all investing in the risk-return trade-off, a discipline against AI-hype claims of high return without risk.",
 sources:["Sharpe, W.F. (1964) 'Capital asset prices', The Journal of Finance, 19(3).","Bodie, Z., Kane, A. and Marcus, A.J. (2021) Investments. New York: McGraw-Hill."]};

C["Diversification Curve"]={
 def:"The Diversification Curve shows how portfolio risk falls as more imperfectly correlated assets are added, approaching but never eliminating undiversifiable systematic risk.",
 who:"Derived from Markowitz's portfolio theory and standard in investment textbooks.",
 why:"It was developed to quantify the benefit and the limit of diversification, distinguishing diversifiable from systematic risk.",
 how:"Risk is plotted against the number of holdings; the curve shows the diminishing benefit of adding assets and the irreducible systematic floor.",
 when:"When designing diversified portfolios.",
 whom:"Portfolio managers and advisers.",
 innov:"It visualises both the power and the boundary of diversification, separating risk that can be diversified away from risk that cannot.",
 sources:["Markowitz, H. (1952) 'Portfolio selection', The Journal of Finance, 7(1).","Statman, M. (1987) 'How many stocks make a diversified portfolio?', Journal of Financial and Quantitative Analysis, 22(3)."]};

C["Capital Asset Pricing Model"]={
 def:"The Capital Asset Pricing Model (CAPM) relates an asset's expected return to its systematic risk (beta), pricing the market risk that cannot be diversified away.",
 who:"Developed independently by William Sharpe, John Lintner and Jan Mossin in the 1960s, building on Markowitz; Sharpe shared the Nobel Prize.",
 why:"It was developed to price risk, providing a benchmark expected return for an asset given its exposure to market risk.",
 how:"Expected return is computed from the risk-free rate, beta and the market risk premium; assets are assessed against this benchmark.",
 when:"When pricing risk, estimating cost of capital and benchmarking returns.",
 whom:"Analysts, portfolio managers and corporate-finance teams.",
 innov:"It introduced beta as the price of systematic risk, a cornerstone of modern asset pricing that frames AI-driven return claims.",
 sources:["Sharpe, W.F. (1964) 'Capital asset prices', The Journal of Finance, 19(3).","Lintner, J. (1965) 'The valuation of risk assets', Review of Economics and Statistics, 47(1)."]};

C["Black-Litterman Model"]={
 def:"The Black-Litterman Model blends an investor's subjective views with the market-equilibrium expected returns to produce stable, intuitive portfolio allocations, addressing the instability of naïve mean-variance optimisation.",
 who:"Developed by Fischer Black and Robert Litterman at Goldman Sachs in the early 1990s.",
 why:"It was developed to fix the extreme, unstable portfolios that pure Markowitz optimisation produces when fed noisy return estimates.",
 how:"Market-implied returns are taken as a prior and adjusted by the investor's stated views with associated confidence, yielding balanced allocations.",
 when:"When constructing portfolios that combine market information with active views, including AI-generated signals.",
 whom:"Quantitative portfolio managers and asset allocators.",
 innov:"It married Bayesian reasoning with portfolio theory, producing robust allocations and a principled way to incorporate AI-derived views.",
 sources:["Black, F. and Litterman, R. (1992) 'Global portfolio optimization', Financial Analysts Journal, 48(5).","He, G. and Litterman, R. (1999) 'The intuition behind Black-Litterman model portfolios', Goldman Sachs."]};

C["Fintech Disruption Map"]={
 def:"The Fintech Disruption Map locates where AI and digital technology are re-pricing or unbundling financial services, from payments and lending to advice and trading.",
 who:"A construct from fintech-strategy analysis, reflecting industry and consultancy mapping of financial-services disruption.",
 why:"It was developed to help incumbents and entrants see where value is migrating as AI reshapes finance.",
 how:"Financial-services activities are mapped by their exposure to AI-driven disruption and unbundling; strategy follows the migration of value.",
 when:"When analysing competitive threats and opportunities in financial services.",
 whom:"Financial-services strategists, investors and product leaders.",
 innov:"It gives a structured view of where AI is genuinely re-pricing finance rather than treating disruption as uniform.",
 sources:["Philippon, T. (2016) 'The fintech opportunity', NBER Working Paper 22476.","World Economic Forum (2017) Beyond Fintech. Geneva: WEF."]};

C["ML Adoption Curve (Investing)"]={
 def:"The ML Adoption Curve for investment management describes the stages by which investment firms move from experimentation with machine learning to its full integration into the investment process.",
 who:"Associated with Peter Muldowney's analysis of machine-learning adoption in investment management.",
 why:"It was developed to help investment firms locate their ML maturity and plan a realistic path to integration.",
 how:"The firm places itself on the curve and identifies the data, talent and governance needed to advance without over-reaching.",
 when:"When planning ML adoption in asset and investment management.",
 whom:"CIOs, quantitative teams and investment-operations leaders.",
 innov:"It frames ML adoption in investing as a staged journey, countering the assumption that capability can be acquired instantly.",
 sources:["Muldowney, P. (2019) 'Machine learning in investment management', industry analysis.","López de Prado, M. (2019) 'Ten applications of financial machine learning', SSRN."]};

C["Robo-Advisory Stack"]={
 def:"The Robo-Advisory Stack layers the components of automated investment advice — client profiling, portfolio allocation, execution and rebalancing — showing how AI automates the advisory process.",
 who:"A construct from wealth-management practice as robo-advisers such as Betterment and Wealthfront emerged.",
 why:"It was developed to clarify how automated advice is assembled and where human judgment and AI each contribute.",
 how:"Each layer is examined for automation and oversight; the stack guides design and governance of automated advice.",
 when:"When designing or assessing automated and hybrid advisory services.",
 whom:"Wealth-management, product and compliance leaders.",
 innov:"It decomposes automated advice into governable layers, clarifying where AI adds value and where fiduciary judgment remains.",
 sources:["Philippon, T. (2019) 'On fintech and financial inclusion', NBER Working Paper 26330.","D'Acunto, F., Prabhala, N. and Rossi, A.G. (2019) 'The promises and pitfalls of robo-advising', Review of Financial Studies, 32(5)."]};

C["Alt-Data Pyramid"]={
 def:"The Alt-Data Pyramid organises alternative data sources — such as satellite imagery, card transactions and web traffic — by their rawness and the processing required to turn them into investment signals (alpha).",
 who:"A construct from quantitative-investing and alternative-data practice.",
 why:"It was developed to show that alternative data must be processed and validated, not merely acquired, to yield genuine signal.",
 how:"Sources are arranged from raw data up to processed alpha signals; investment in processing targets where signal can be extracted.",
 when:"When sourcing and evaluating alternative data for investment.",
 whom:"Quantitative investors and data teams.",
 innov:"It clarifies that alternative data's value lies in processing and uniqueness, not mere possession, tempering alt-data hype.",
 sources:["Kolanovic, M. and Krishnamachari, R.T. (2017) Big Data and AI Strategies. J.P. Morgan.","Monk, A., Prins, M. and Rook, D. (2019) 'Rethinking alternative data in institutional investment', Journal of Financial Data Science, 1(1)."]};

C["Blockchain Instrument Map"]={
 def:"The Blockchain Instrument Map surveys tokenised and smart-contract-based financial instruments, clarifying how distributed-ledger technology creates new asset types and settlement mechanisms.",
 who:"A construct from digital-asset and decentralised-finance analysis.",
 why:"It was developed to help investors understand the landscape of blockchain-based instruments and their distinct risks.",
 how:"Instruments are mapped by type and mechanism; their characteristics and risks are assessed against traditional analogues.",
 when:"When evaluating digital-asset and tokenised investments.",
 whom:"Investors, product and risk teams.",
 innov:"It organises a fast-evolving instrument landscape, supporting disciplined assessment rather than speculation.",
 sources:["Catalini, C. and Gans, J.S. (2020) 'Some simple economics of the blockchain', Communications of the ACM, 63(7).","BIS (2023) 'The crypto ecosystem: key elements and risks', Bank for International Settlements."]};

C["Fama-French Factors"]={
 def:"The Fama-French model explains asset returns using multiple factors beyond market risk — notably size and value, later extended to profitability and investment — showing returns have more than one systematic source.",
 who:"Developed by Eugene Fama and Kenneth French, beginning with their 1992–1993 three-factor model; Fama shared the Nobel Prize.",
 why:"It was developed because the single-factor CAPM failed to explain observed return patterns associated with firm size and value.",
 how:"Returns are decomposed into exposures to the factors; portfolios are constructed and evaluated by their factor loadings.",
 when:"When explaining returns, constructing factor portfolios and evaluating AI-generated strategies.",
 whom:"Quantitative investors, analysts and academics.",
 innov:"It established multi-factor asset pricing, showing that returns reward several systematic exposures, not market risk alone.",
 sources:["Fama, E.F. and French, K.R. (1993) 'Common risk factors in the returns on stocks and bonds', Journal of Financial Economics, 33(1).","Fama, E.F. and French, K.R. (2015) 'A five-factor asset pricing model', Journal of Financial Economics, 116(1)."]};

C["Risk-Profiling Matrix"]={
 def:"The Risk-Profiling Matrix assesses an investor by both risk capacity (ability to bear loss) and risk tolerance (willingness to bear it), guiding suitable portfolio risk.",
 who:"A construct from financial-advice and suitability practice, reflected in regulatory suitability requirements.",
 why:"It was developed to ensure portfolios match both the investor's financial ability and psychological willingness to bear risk.",
 how:"The investor is placed by capacity and tolerance; portfolio risk is set to the lower of the two to ensure suitability.",
 when:"When determining suitable investment risk, including in robo-advice.",
 whom:"Advisers, wealth managers and compliance teams.",
 innov:"It separates capacity from tolerance, preventing mismatches that pure questionnaire scores miss.",
 sources:["Grable, J.E. and Lytton, R.H. (1999) 'Financial risk tolerance revisited', Financial Services Review, 8(3).","FCA (2011) 'Assessing suitability', Financial Conduct Authority."]};

C["Prediction Machines Lens"]={
 def:"The Prediction Machines Lens frames AI economically as a drop in the cost of prediction, clarifying that AI makes prediction cheap while judgment, data and action remain complementary and human.",
 who:"Developed by economists Ajay Agrawal, Joshua Gans and Avi Goldfarb in Prediction Machines (2018).",
 why:"It was developed to give a clear economic account of what AI does — lower the cost of prediction — and what it does not replace.",
 how:"AI opportunities are analysed by identifying where cheaper prediction creates value and where human judgment must still be supplied.",
 when:"When assessing where AI adds value in investment and decision processes.",
 whom:"Investors, strategists and decision-makers.",
 innov:"It reframes AI as a prediction technology, separating cheap prediction from the judgment that remains decisive — vital where AI meets finance.",
 sources:["Agrawal, A., Gans, J. and Goldfarb, A. (2018) Prediction Machines. Boston: HBR Press.","Agrawal, A., Gans, J. and Goldfarb, A. (2022) Power and Prediction. Boston: HBR Press."]};

C["Backtesting Pitfalls Map"]={
 def:"The Backtesting Pitfalls Map catalogues the ways historical strategy tests mislead — overfitting, look-ahead bias, survivorship bias and multiple testing — so apparent edges can be scrutinised.",
 who:"Associated with Marcos López de Prado's work on the dangers of backtesting in financial machine learning.",
 why:"It was developed because AI makes it trivially easy to find spurious patterns, and most spectacular backtests are false discoveries.",
 how:"A backtest is examined against each pitfall; only strategies that survive scrutiny and out-of-sample testing are trusted.",
 when:"When evaluating quantitative and AI-driven investment strategies.",
 whom:"Quantitative investors, risk and research teams.",
 innov:"It systematises scepticism toward backtests, a crucial discipline as AI multiplies the risk of false discovery.",
 sources:["López de Prado, M. (2018) Advances in Financial Machine Learning. Hoboken: Wiley.","Bailey, D.H. et al. (2014) 'Pseudo-mathematics and financial charlatanism', Notices of the AMS, 61(5)."]};

C["Monte Carlo Cone"]={
 def:"The Monte Carlo Cone visualises the distribution of possible future outcomes generated by simulating many random scenarios, replacing a single point forecast with a fan of probabilities.",
 who:"Based on the Monte Carlo method developed by Stanislaw Ulam and John von Neumann, widely applied in finance.",
 why:"It was developed to represent uncertainty honestly, showing the range and likelihood of outcomes rather than a misleading single estimate.",
 how:"Many simulated paths are generated from assumed distributions; the resulting cone shows the spread of plausible outcomes for planning.",
 when:"When modelling uncertain investment and financial outcomes.",
 whom:"Analysts, risk managers and planners.",
 innov:"It communicates uncertainty as a distribution, countering false precision in forecasts — including AI-generated ones.",
 sources:["Metropolis, N. and Ulam, S. (1949) 'The Monte Carlo method', Journal of the American Statistical Association, 44(247).","Glasserman, P. (2003) Monte Carlo Methods in Financial Engineering. New York: Springer."]};

C["Algo-Trading Pipeline"]={
 def:"The Algorithmic Trading Pipeline describes the flow from signal generation through execution to monitoring, showing how automated strategies translate data into trades and manage their consequences.",
 who:"A construct from quantitative-finance and trading-systems practice.",
 why:"It was developed to structure the design and governance of automated trading, where errors propagate at machine speed.",
 how:"Each stage — signal, execution, monitoring — is designed with controls; the pipeline clarifies where risk and oversight must sit.",
 when:"When designing or governing algorithmic trading systems.",
 whom:"Quantitative traders, engineers and risk teams.",
 innov:"It makes the end-to-end automated trading process explicit and governable, emphasising monitoring as integral, not optional.",
 sources:["Chan, E.P. (2013) Algorithmic Trading: Winning Strategies and Their Rationale. Hoboken: Wiley.","Aldridge, I. (2013) High-Frequency Trading. Hoboken: Wiley."]};

C["Latency Arms Race"]={
 def:"The Latency Arms Race describes the competitive pursuit of ever-lower trading latency, where microseconds of speed advantage translate into profit, driving heavy investment in infrastructure.",
 who:"A phenomenon documented in market-microstructure and high-frequency-trading research.",
 why:"It is described to explain the economics and risks of speed competition in modern markets.",
 how:"The value of marginal speed is weighed against its cost and systemic risk; participants decide how far to compete on latency.",
 when:"When analysing high-frequency trading strategy and market structure.",
 whom:"Trading-firm strategists, regulators and researchers.",
 innov:"It captures how speed itself became a contested, costly source of edge, with systemic implications.",
 sources:["Budish, E., Cramton, P. and Shim, J. (2015) 'The high-frequency trading arms race', Quarterly Journal of Economics, 130(4).","MacKenzie, D. (2021) Trading at the Speed of Light. Princeton: PUP."]};

C["Market Microstructure Map"]={
 def:"The Market Microstructure Map describes how orders, order books, spreads and price impact interact to determine how trades are executed and prices formed at a fine-grained level.",
 who:"Grounded in the field of market microstructure, associated with scholars such as Maureen O'Hara and Larry Harris.",
 why:"It was developed to understand price formation and trading costs at the level where automated and high-frequency strategies operate.",
 how:"The components of the trading mechanism are mapped to analyse execution cost, liquidity and price impact.",
 when:"When designing execution strategy and analysing trading costs.",
 whom:"Traders, execution and research teams.",
 innov:"It provides the fine-grained view of trading necessary to understand and manage execution in automated markets.",
 sources:["O'Hara, M. (1995) Market Microstructure Theory. Cambridge: Blackwell.","Harris, L. (2003) Trading and Exchanges. Oxford: OUP."]};

C["Flash-Crash Risk Loop"]={
 def:"The Flash-Crash Risk Loop describes how automated trading can amplify shocks through feedback — rapid selling triggering further automated selling — producing sudden, severe market dislocations.",
 who:"Analysed in studies of events such as the 2010 Flash Crash and broader research on automation and market stability.",
 why:"It was developed to explain how speed and automation can interact to destabilise markets, informing safeguards.",
 how:"Feedback dynamics are mapped to identify amplification risks; circuit breakers and controls are designed to interrupt the loop.",
 when:"When assessing systemic risk in automated markets and designing safeguards.",
 whom:"Regulators, risk managers and trading-system designers.",
 innov:"It frames automation as a potential amplifier of shocks, motivating controls such as circuit breakers.",
 sources:["Kirilenko, A. et al. (2017) 'The Flash Crash: High-frequency trading in an electronic market', Journal of Finance, 72(3).","CFTC-SEC (2010) Findings Regarding the Market Events of May 6, 2010."]};

C["Execution Cost Frontier"]={
 def:"The Execution Cost Frontier expresses the trade-off between trading speed and market impact (slippage): trading faster moves the price against you, while trading slowly risks adverse moves.",
 who:"Grounded in optimal-execution research, notably the Almgren-Chriss framework.",
 why:"It was developed to optimise trade execution by balancing the cost of speed against the risk of delay.",
 how:"Execution strategies are placed on the frontier; the schedule is chosen to minimise total expected cost given risk preferences.",
 when:"When executing large trades and designing execution algorithms.",
 whom:"Traders, execution teams and quantitative researchers.",
 innov:"It formalises the speed-versus-impact trade-off, underpinning algorithmic execution strategy.",
 sources:["Almgren, R. and Chriss, N. (2001) 'Optimal execution of portfolio transactions', Journal of Risk, 3(2).","Kissell, R. (2013) The Science of Algorithmic Trading and Portfolio Management. London: Academic Press."]};

// ============ UNIT 7 — Innovative AI Enterprises: Unicorns & Scaling ============
C["AI Startup Valuation Stack"]={
 def:"The AI Startup Valuation Stack identifies what an AI-first company is actually valued on — team, proprietary data, traction and defensibility — beyond headline revenue multiples.",
 who:"A synthesis from venture-valuation practice applied to AI-first companies.",
 why:"It was developed to look past revenue multiples to the strategic assets that justify and sustain an AI venture's valuation.",
 how:"The company is assessed layer by layer; weak layers (e.g. no defensibility) flag valuation risk despite strong revenue.",
 when:"During fundraising, investment due diligence and valuation.",
 whom:"Founders, investors and corporate-development teams.",
 innov:"It grounds AI valuation in durable strategic assets rather than growth alone, exposing fragile high-valuation companies.",
 sources:["Damodaran, A. (2018) The Dark Side of Valuation. 3rd edn. Upper Saddle River: Pearson.","Gornall, W. and Strebulaev, I.A. (2020) 'Squaring venture capital valuations with reality', Journal of Financial Economics, 135(1)."]};

C["Cost-Structure Lens"]={
 def:"The Cost-Structure Lens examines the gross-margin reality of an AI product, recognising that inference, data and human-in-the-loop costs can erode the high margins assumed for software.",
 who:"A construct from SaaS and AI-economics analysis, prominent in the debate over generative-AI unit economics.",
 why:"It was developed because AI products often carry variable costs (compute, review) that classic software margins ignore.",
 how:"The full cost of serving each unit is analysed; pricing and strategy adjust to the true, often lower, gross margin.",
 when:"When assessing the economics and scalability of AI products.",
 whom:"Founders, finance leaders and investors.",
 innov:"It punctures the assumption of software-like margins for AI, exposing the inference and labour costs beneath them.",
 sources:["a16z (2023) 'Navigating the high cost of AI compute'.","Bessemer Venture Partners (2023) 'State of the cloud'."]};

C["Rule of 40"]={
 def:"The Rule of 40 holds that a healthy software or AI company's growth rate plus profit margin should sum to at least 40%, balancing growth against profitability.",
 who:"A heuristic popularised by venture and growth investors, attributed to Brad Feld and widely used in SaaS analysis.",
 why:"It was developed as a quick test of whether a company's growth is being achieved at acceptable economic cost.",
 how:"Growth rate and profit margin are summed; a result of 40 or more signals a healthy balance, prompting scrutiny if below.",
 when:"When assessing the health and fundability of growth-stage AI companies.",
 whom:"Founders, investors and finance leaders.",
 innov:"It provides a single, memorable test balancing growth and profitability, widely adopted in growth-stage investing.",
 sources:["Feld, B. (2015) 'The rule of 40% for a healthy SaaS company', Feld Thoughts.","Bain & Company (2021) 'The Rule of 40'."]};

C["Strategic Asset Map"]={
 def:"The Strategic Asset Map identifies what an acquirer or investor actually pays for in an AI company — data, talent, technology, customers or market position — clarifying where durable value resides.",
 who:"A construct from corporate-development and M&A practice applied to AI companies.",
 why:"It was developed to focus value creation on the assets that command a premium in acquisition or investment.",
 how:"The company's assets are mapped and assessed for transferability and scarcity; strategy strengthens the most valuable.",
 when:"During strategy, fundraising and M&A preparation.",
 whom:"Founders, corporate-development and investors.",
 innov:"It clarifies which assets create acquisition or investment value, guiding where an AI company should build moats.",
 sources:["Capron, L. and Mitchell, W. (2012) Build, Borrow, or Buy. Boston: HBR Press.","Damodaran, A. (2018) The Dark Side of Valuation. Upper Saddle River: Pearson."]};

C["Investor Expectation Curve"]={
 def:"The Investor Expectation Curve maps the milestones investors expect at each funding stage, from seed through growth rounds, clarifying what a company must demonstrate to raise the next round.",
 who:"A construct from venture-financing practice describing stage-appropriate expectations.",
 why:"It was developed to align founders' progress with the evidence investors require at each stage.",
 how:"The company's stage is matched to expected milestones; the gap defines what must be achieved before the next raise.",
 when:"During fundraising planning across stages.",
 whom:"Founders, investors and finance leaders.",
 innov:"It makes stage-by-stage investor expectations explicit, helping AI ventures time and target their raises.",
 sources:["Feld, B. and Mendelson, J. (2019) Venture Deals. 4th edn. Hoboken: Wiley.","Gompers, P. and Lerner, J. (2004) The Venture Capital Cycle. Cambridge: MIT Press."]};

C["Growth Loops"]={
 def:"Growth Loops are self-reinforcing systems where each cycle's output fuels the next cycle's input, producing compounding growth that linear funnels cannot capture.",
 who:"Articulated by growth practitioners, notably Brian Balfour and the Reforge community.",
 why:"It was developed to capture how durable products grow through reinvested output rather than one-off acquisition.",
 how:"The loop and its reinvestment mechanism are mapped; AI and product effort target strengthening the loop.",
 when:"When designing scalable growth engines for AI products.",
 whom:"Growth, product and strategy leaders.",
 innov:"It reframes growth as compounding loops, focusing scaling effort on reinforcing mechanisms.",
 sources:["Balfour, B. (2017) 'Growth loops are the new funnels', Reforge.","Ellis, S. and Brown, M. (2017) Hacking Growth. New York: Currency."]};

C["Product-Led Growth"]={
 def:"Product-Led Growth (PLG) is a strategy in which the product itself drives acquisition, conversion and expansion, with users experiencing value before, or instead of, a sales conversation.",
 who:"Popularised by the OpenView venture firm and product-led practitioners as a dominant software go-to-market model.",
 why:"It was developed to lower acquisition cost and accelerate growth by letting the product do the selling.",
 how:"The product is designed for self-serve value, virality and expansion; metrics track activation and product-qualified leads.",
 when:"When designing go-to-market for AI products with self-serve potential.",
 whom:"Product, growth and go-to-market leaders.",
 innov:"It shifts the growth engine from sales to the product, often lowering cost of acquisition for AI-enabled software.",
 sources:["Bush, W. (2019) Product-Led Growth. ProductLed.","OpenView (2021) 'The product-led growth playbook'."]};

C["Network Effects Map"]={
 def:"A Network Effects Map distinguishes the types of network effect — direct, indirect (two-sided), and data — that can make a product more valuable as more people use it.",
 who:"Grounded in platform-economics theory, associated with scholars such as Katz and Shapiro and the platform work of Parker, Van Alstyne and Choudary.",
 why:"It was developed to identify whether and how a product benefits from network effects, a key source of durable advantage.",
 how:"The product is examined for each type of effect; strategy strengthens the effects that compound advantage.",
 when:"When assessing platform and AI-product defensibility.",
 whom:"Founders, product and strategy leaders.",
 innov:"It distinguishes types of network effect rather than treating them as one, clarifying where compounding advantage actually arises.",
 sources:["Katz, M.L. and Shapiro, C. (1985) 'Network externalities, competition, and compatibility', American Economic Review, 75(3).","Parker, G., Van Alstyne, M. and Choudary, S.P. (2016) Platform Revolution. New York: Norton."]};

C["T2D3 Trajectory"]={
 def:"T2D3 describes a hyper-growth revenue trajectory — triple, triple, double, double, double — that some software companies follow on the path from early traction to scale.",
 who:"Articulated by venture investor Neeraj Agrawal of Battery Ventures as a benchmark for SaaS hyper-growth.",
 why:"It was developed as a benchmark for the growth pace that defines breakout software companies.",
 how:"A company's year-on-year growth is compared with the T2D3 path to gauge whether it is on a breakout trajectory.",
 when:"When benchmarking growth-stage AI and software companies.",
 whom:"Founders and investors.",
 innov:"It gives a memorable, ambitious growth benchmark, clarifying the pace expected of breakout ventures.",
 sources:["Agrawal, N. (2015) 'The SaaS adventure', TechCrunch.","Battery Ventures (2018) 'Scaling to $100M ARR'."]};

C["Flywheel Model"]={
 def:"The Flywheel Model depicts business momentum as a heavy wheel that, once pushed consistently in one direction, accumulates and compounds momentum over time.",
 who:"Popularised by Jim Collins in Good to Great (2001) as a metaphor for how breakthroughs are built cumulatively.",
 why:"It was developed to counter the myth of the single decisive move, showing that durable success compounds from consistent effort.",
 how:"The reinforcing components of the business are identified and pushed consistently so momentum compounds rather than resets.",
 when:"When building and communicating a compounding growth strategy.",
 whom:"Founders, executives and strategists.",
 innov:"It reframes success as cumulative momentum rather than a single breakthrough, guiding consistent strategic effort.",
 sources:["Collins, J. (2001) Good to Great. New York: HarperBusiness.","Collins, J. (2019) Turning the Flywheel. New York: HarperBusiness."]};

C["Vertical vs. Platform 2×2"]={
 def:"The Vertical-vs-Platform matrix contrasts vertical AI strategies that go deep in one industry with platform strategies that go broad across sectors, mapping industry depth against breadth of reach.",
 who:"A contemporary venture-strategy framing from the debate over how AI companies should position themselves.",
 why:"It was developed to clarify a fundamental strategic choice for AI ventures: depth in a vertical or breadth as a platform.",
 how:"A venture is placed by its depth and breadth; the position implies distinct moats, go-to-market and scaling paths.",
 when:"When setting AI-venture strategy and positioning.",
 whom:"Founders, investors and strategists.",
 innov:"It names the depth-versus-breadth choice central to AI-venture strategy, with different defensibility on each path.",
 sources:["a16z (2023) 'The economic case for vertical AI'.","Moore, G. (1991) Crossing the Chasm. New York: HarperBusiness."]};

C["Wedge-to-Platform Path"]={
 def:"The Wedge-to-Platform Path describes how a company enters with a narrow, sharp 'wedge' product and expands from that beachhead into a broader platform over time.",
 who:"A venture-strategy construct drawing on Moore's beachhead strategy and platform-expansion thinking.",
 why:"It was developed to show how durable platforms are built — by winning a narrow wedge first, not by launching broad.",
 how:"The wedge is chosen for sharpness and expandability; expansion follows once the beachhead is secured.",
 when:"When planning AI-venture entry and expansion strategy.",
 whom:"Founders, product and strategy leaders.",
 innov:"It charts the realistic path from a focused entry point to a broad platform, countering premature breadth.",
 sources:["Moore, G. (1991) Crossing the Chasm. New York: HarperBusiness.","Parker, G., Van Alstyne, M. and Choudary, S.P. (2016) Platform Revolution. New York: Norton."]};

C["Category Design Map"]={
 def:"The Category Design Map guides a company in creating and owning a new market category, rather than competing within an existing one, by defining the problem and the category it solves.",
 who:"Articulated by Al Ramadan, Dave Peterson, Christopher Lochhead and Kevin Maney in Play Bigger (2016).",
 why:"It was developed on the observation that category creators capture a disproportionate share of a category's value.",
 how:"The company defines a new category, frames the problem it addresses, and invests in making the category — and itself as its leader — known.",
 when:"When an AI venture can define and lead a new category.",
 whom:"Founders, marketing and strategy leaders.",
 innov:"It reframes competition as category creation, where defining the game can be more valuable than winning an existing one.",
 sources:["Ramadan, A. et al. (2016) Play Bigger. New York: Harper Business.","Lochhead, C. and Peterson, D. (2018) Niche Down. Self-published."]};

C["TAM-SAM-SOM Funnel"]={
 def:"The TAM-SAM-SOM funnel sizes a market in three nested layers — Total Addressable Market, Serviceable Addressable Market and Serviceable Obtainable Market — to ground growth ambitions in realistic opportunity.",
 who:"A standard market-sizing construct in venture and strategy practice.",
 why:"It was developed to discipline market-size claims, distinguishing the theoretical maximum from the realistically obtainable.",
 how:"The total market is narrowed to what the firm can serve and then to what it can realistically obtain, grounding projections.",
 when:"During fundraising, planning and market-entry analysis.",
 whom:"Founders, investors and strategists.",
 innov:"It separates aspirational market size from obtainable share, tempering inflated AI-market claims.",
 sources:["Blank, S. (2013) The Startup Owner's Manual. Pescadero: K&S Ranch.","Mullins, J. (2017) The Customer-Funded Business. Hoboken: Wiley."]};

C["Platform vs. Pipe"]={
 def:"The Platform-vs-Pipe distinction contrasts platforms that orchestrate value created by others with pipes that produce and sell value linearly, explaining why platforms often scale and defend better.",
 who:"Articulated by Sangeet Paul Choudary and colleagues in Platform Revolution (2016).",
 why:"It was developed to explain the rise of platform businesses and why they outcompete traditional linear 'pipe' firms.",
 how:"A business model is classified as platform or pipe; platform strategy focuses on orchestrating and governing an ecosystem.",
 when:"When choosing and assessing AI-venture business models.",
 whom:"Founders, strategists and investors.",
 innov:"It crystallised why platforms beat pipes, reframing strategy around orchestration rather than linear production.",
 sources:["Parker, G., Van Alstyne, M. and Choudary, S.P. (2016) Platform Revolution. New York: Norton.","Van Alstyne, M., Parker, G. and Choudary, S.P. (2016) 'Pipelines, platforms, and the new rules of strategy', Harvard Business Review, 94(4)."]};

C["The Scaling Funnel"]={
 def:"The Scaling Funnel depicts the steep attrition of startups across funding stages, from seed through to scale, illustrating the low survival rates and what distinguishes survivors.",
 who:"A construct drawn from venture-financing data and survival analysis of startups.",
 why:"It was developed to set realistic expectations about scaling and to identify what separates companies that survive each stage.",
 how:"A company's stage and survival odds are assessed; effort focuses on the factors — defensibility, unit economics — that aid survival.",
 when:"When planning and assessing the scaling journey.",
 whom:"Founders and investors.",
 innov:"It makes the brutal attrition of scaling explicit, focusing attention on the determinants of survival rather than valuation alone.",
 sources:["CB Insights (2021) 'The top 12 reasons startups fail'.","Gompers, P. and Lerner, J. (2004) The Venture Capital Cycle. Cambridge: MIT Press."]};

C["Blitzscaling Lens"]={
 def:"The Blitzscaling Lens prioritises speed over efficiency to capture a market before rivals when winner-takes-most dynamics apply, accepting inefficiency and risk in pursuit of scale.",
 who:"Developed by Reid Hoffman and Chris Yeh in Blitzscaling (2018), drawing on Silicon Valley scaling experience.",
 why:"It was developed to explain when prioritising breakneck growth over efficiency is the right strategy — and when it is not.",
 how:"Market dynamics are assessed for winner-takes-most conditions; if present, the company prioritises speed, accepting inefficiency.",
 when:"When market dynamics reward being first to scale.",
 whom:"Founders, executives and investors.",
 innov:"It articulates the deliberate choice of speed over efficiency under specific market conditions, with explicit acknowledgment of its risks.",
 sources:["Hoffman, R. and Yeh, C. (2018) Blitzscaling. New York: Currency.","Sullivan, T. (2016) 'Blitzscaling', Harvard Business Review, 94(4)."]};

C["Stages of Scale"]={
 def:"The Stages of Scale describe how an organisation transforms as it grows — from a small founder-led team to a professionally managed company — with distinct challenges at each stage.",
 who:"Drawing on organisational-growth models such as Greiner's stages of growth.",
 why:"It was developed to anticipate the organisational crises and transitions that accompany rapid growth.",
 how:"The company's stage is identified; leadership and structure are evolved to meet the next stage's demands.",
 when:"When scaling an organisation and anticipating growing pains.",
 whom:"Founders, executives and HR leaders.",
 innov:"It frames scaling as a series of organisational transformations, not merely getting bigger, preparing leaders for predictable crises.",
 sources:["Greiner, L.E. (1972) 'Evolution and revolution as organizations grow', Harvard Business Review, 50(4).","Wasserman, N. (2012) The Founder's Dilemmas. Princeton: PUP."]};

C["Unicorn Anatomy"]={
 def:"Unicorn Anatomy examines the common characteristics of companies that reach a billion-dollar valuation — large markets, strong defensibility, exceptional teams and compounding advantages — to identify the DNA of breakout success.",
 who:"A construct from venture analysis of high-valuation companies, building on Aileen Lee's coining of the term 'unicorn'.",
 why:"It was developed to identify recurring traits of breakout companies, while cautioning that valuation alone is not durability.",
 how:"A company is assessed against the recurring traits; gaps indicate where durability must be strengthened.",
 when:"When assessing breakout potential and durability of AI ventures.",
 whom:"Founders, investors and strategists.",
 innov:"It dissects what billion-dollar companies share, while warning that the valuation label is an output, not a strategy.",
 sources:["Lee, A. (2013) 'Welcome to the unicorn club', TechCrunch.","Gornall, W. and Strebulaev, I.A. (2020) 'Squaring venture capital valuations with reality', Journal of Financial Economics, 135(1)."]};

C["Beyond Unicorn — Durability"]={
 def:"Beyond-Unicorn Durability shifts the focus from achieving a billion-dollar valuation to building lasting competitive advantage, arguing that durable value, not the valuation label, is the real goal.",
 who:"A synthesis from strategy and venture thinking emphasising durability over valuation milestones.",
 why:"It was developed to counter the chasing of unicorn status, which can produce fragile companies, in favour of lasting advantage.",
 how:"The company is assessed on durable advantage — moats, economics, adaptability — rather than valuation, and strategy reinforces durability.",
 when:"When setting long-term strategy beyond growth-stage milestones.",
 whom:"Founders, executives and investors.",
 innov:"It reframes the goal from valuation to durability, the integrative lesson of the capstone unit.",
 sources:["Helmer, H. (2016) 7 Powers. Deep Strategy.","Collins, J. and Porras, J.I. (1994) Built to Last. New York: HarperBusiness."]};

module.exports = C;
